package br.edu.ifrn.sistemachamados.mapper;
import br.edu.ifrn.sistemachamados.dto.response.*; import br.edu.ifrn.sistemachamados.model.*;
public final class ApiMapper { private ApiMapper(){} private static Long id(Object o){if(o instanceof Setor x)return x.getId();if(o instanceof Categoria x)return x.getId();if(o instanceof Usuario x)return x.getId();if(o instanceof Chamado x)return x.getId();return null;} public static SetorResponse setor(Setor x){return new SetorResponse(x.getId(),x.getNome(),x.getSigla());} public static CategoriaResponse categoria(Categoria x){return new CategoriaResponse(x.getId(),x.getNome(),x.getDescricao(),id(x.getSetor()));} public static UsuarioResponse usuario(Usuario x){return new UsuarioResponse(x.getId(),x.getNome(),x.getEmail(),x.getMatricula(),x.getTipo(),id(x.getSetor()));} public static ChamadoResponse chamado(Chamado x){return new ChamadoResponse(x.getId(),x.getTitulo(),x.getDescricao(),x.getLocal(),x.getPrioridade(),x.getStatus(),x.getDataAbertura(),x.getDataFechamento(),x.getSolucao(),id(x.getSolicitante()),id(x.getCategoria()),id(x.getTecnico()));} public static InteracaoResponse interacao(Interacao x){return new InteracaoResponse(x.getId(),x.getTexto(),x.getDataHora(),id(x.getChamado()),id(x.getAutor()));}}
